args.content:
SELECT ?item ?itemLabel ?coordLabel
WHERE {
  ?item wdt:P31 wd:Q1463114 ;
        wdt:P17 wd:Q29 ;
        wdt:P625 ?coord .

  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en".
  }
}

